#!/usr/bin/env bun
// PalanuOS icon tool: turns the pixel-art sources in assets/icons/ into C tables (system/src/icons_data.c and
// system/include/pal/icons_data.h). No dependencies.
//
//   bun forge/tools/icons.ts           write the generated files
//   bun forge/tools/icons.ts --check   fail if the checked-in files are not what the sources produce (./pal check runs this)
//
// Source format: one file per icon and size, named <name>@<size>.txt (name: a-z, 0-9, '-'; size: 8, 16 or 32). Each file is
// a square grid of rows: '#' is an ink pixel, '+' is an accent pixel (drawn in the theme's accent colour), '.' is empty.
// Every row has the same length, which is the icon's width, and the row count is its height.
import { existsSync, readdirSync, readFileSync, writeFileSync } from "node:fs";
import { join, resolve } from "node:path";

const ROOT = resolve(import.meta.dir, "../..");
const SRC_DIR = join(ROOT, "assets/icons");
const OUT_C = join(ROOT, "system/src/icons_data.c");
const OUT_H = join(ROOT, "system/include/pal/icons_data.h");

export interface IconSource {
  name: string;
  size: number;
  w: number;
  h: number;
  ink: string[]; // rows of '#' and '.'
  accent: string[]; // rows of '+' and '.'
}

const NAME_RE = /^([a-z0-9-]+)@(8|16|32)\.txt$/;

/* Parses one source file's text. Throws with a message naming the problem; the caller adds the file name. */
export function parseIcon(name: string, size: number, text: string): IconSource {
  const rows = text.split("\n").filter((l) => l.length > 0);
  if (rows.length === 0) throw new Error("empty icon");
  const w = rows[0].length;
  if (w === 0) throw new Error("empty row");
  if (rows.length !== size) throw new Error(`height ${rows.length}, expected ${size}`);
  if (w !== size) throw new Error(`width ${w}, expected ${size}`);
  const ink: string[] = [];
  const accent: string[] = [];
  rows.forEach((r, y) => {
    if (r.length !== w) throw new Error(`row ${y + 1} has ${r.length} columns, expected ${w}`);
    if (!/^[#.+]*$/.test(r)) throw new Error(`row ${y + 1} has a character other than # . +`);
    ink.push(r.replace(/\+/g, "#"));
    accent.push(r.replace(/#/g, ".").replace(/\+/g, "+"));
  });
  return { name, size, w, h: size, ink, accent };
}

/* Packs rows into bytes, MSB first, each row padded to whole bytes. */
export function packBits(rows: string[], ch: string, w: number): number[] {
  const bpr = (w + 7) >> 3;
  const out: number[] = [];
  for (const r of rows) {
    for (let b = 0; b < bpr; b++) {
      let v = 0;
      for (let k = 0; k < 8; k++) {
        const x = b * 8 + k;
        if (x < w && r[x] === ch) v |= 0x80 >> k;
      }
      out.push(v);
    }
  }
  return out;
}

const hex = (bytes: number[]) =>
  bytes.map((b, i) => (i % 12 === 0 ? "\n    " : " ") + "0x" + b.toString(16).padStart(2, "0") + ",").join("");

const cident = (name: string, size: number) => `${name.replace(/-/g, "_")}_${size}`;

/* Reads every source in dir and produces the two generated files. Errors are collected, not thrown. */
export function generate(dir: string): { c: string; h: string; errors: string[]; count: number } {
  const errors: string[] = [];
  const icons: IconSource[] = [];
  const files = existsSync(dir) ? readdirSync(dir).sort() : [];
  for (const f of files) {
    if (!f.endsWith(".txt")) continue;
    const m = NAME_RE.exec(f);
    if (!m) {
      errors.push(`${f}: name must be <name>@<8|16|32>.txt`);
      continue;
    }
    try {
      icons.push(parseIcon(m[1], Number(m[2]), readFileSync(join(dir, f), "utf8")));
    } catch (e) {
      errors.push(`${f}: ${(e as Error).message}`);
    }
  }
  const seen = new Set<string>();
  for (const i of icons) {
    const k = `${i.name}@${i.size}`;
    if (seen.has(k)) errors.push(`${k}: duplicate`);
    seen.add(k);
  }

  const body: string[] = [];
  const table: string[] = [];
  for (const i of icons) {
    const id = cident(i.name, i.size);
    const bits = packBits(i.ink, "#", i.w);
    const hasAccent = i.accent.some((r) => r.includes("+"));
    body.push(`static const uint8_t ICON_${id}_BITS[] = {${hex(bits)}\n};`);
    if (hasAccent) body.push(`static const uint8_t ICON_${id}_ACCENT[] = {${hex(packBits(i.accent, "+", i.w))}\n};`);
    table.push(
      `    {"${i.name}", ${i.size}, ${i.w}, ${i.h}, ICON_${id}_BITS, ${hasAccent ? `ICON_${id}_ACCENT` : "NULL"}},`,
    );
  }
  const c = [
    "/* GENERATED by forge/tools/icons.ts from the sources in assets/icons (one .txt per icon). Do not edit by hand: change the sources and run",
    " * bun forge/tools/icons.ts (./pal check fails when this file is out of date). */",
    '#include "pal/icons_data.h"',
    "",
    ...body,
    "",
    "const pal_icon_t PAL_ICONS[] = {",
    ...table,
    "};",
    `const size_t PAL_ICONS_COUNT = sizeof(PAL_ICONS) / sizeof(PAL_ICONS[0]);`,
    "",
  ].join("\n");
  const h = [
    "/* GENERATED by forge/tools/icons.ts from the sources in assets/icons (one .txt per icon). Do not edit by hand. */",
    "#ifndef PAL_ICONS_DATA_H",
    "#define PAL_ICONS_DATA_H",
    "",
    "#include <stddef.h>",
    "#include <stdint.h>",
    "",
    "/* One pixel-art icon. bits: ink pixels, rows padded to whole bytes, MSB first. accent: the '+' pixels, or NULL. */",
    "typedef struct {",
    "    const char *name;",
    "    uint8_t size;   /* the source size: 8, 16 or 32 */",
    "    uint8_t w, h;",
    "    const uint8_t *bits;",
    "    const uint8_t *accent;",
    "} pal_icon_t;",
    "",
    "extern const pal_icon_t PAL_ICONS[];",
    "extern const size_t PAL_ICONS_COUNT;",
    "",
    "#endif",
    "",
  ].join("\n");
  return { c, h, errors, count: icons.length };
}

function main(argv: string[]): number {
  const check = argv.includes("--check");
  const g = generate(SRC_DIR);
  if (g.errors.length) {
    for (const e of g.errors) console.error(`icons: ${e}`);
    return 1;
  }
  if (check) {
    const stale = [OUT_C, OUT_H].filter((p) => !existsSync(p) || readFileSync(p, "utf8") !== (p === OUT_C ? g.c : g.h));
    for (const p of stale) console.error(`icons: ${p.slice(ROOT.length + 1)} is out of date; run: bun forge/tools/icons.ts`);
    if (stale.length) return 1;
    console.log(`icons: ${g.count} icons up to date`);
    return 0;
  }
  writeFileSync(OUT_C, g.c);
  writeFileSync(OUT_H, g.h);
  console.log(`icons: wrote ${g.count} icons`);
  return 0;
}

if (import.meta.main) process.exit(main(process.argv.slice(2)));
